class Config:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

a = Config()
b = Config()
print(a is b)

def shape_factory(kind):
    if kind == 'circle':
        return lambda r: 3.14 * r * r
    if kind == 'square':
        return lambda a: a * a
    raise ValueError(kind)

area = shape_factory('square')
print(area(5))

def sort_desc(data):
    return sorted(data, reverse=True)

def sort_by_len(data):
    return sorted(data, key=len)

def process(data, strategy):
    return strategy(data)

print(process([3,1,2], sort_desc))
print(process(['bb','a','ccc'], sort_by_len))

class Event:
    def __init__(self):
        self.subs = []

    def subscribe(self, fn):
        self.subs.append(fn)

    def fire(self, msg):
        for fn in self.subs:
            fn(msg)

ev = Event()
ev.subscribe(lambda m: print('邮件:', m))
ev.subscribe(lambda m: print('短信:', m))
ev.fire('服务器重启')

def vip(price):
    return price * 0.8

def normal(price):
    return price

def checkout(price, policy):
    return policy(price)

print(checkout(100, vip))
print(checkout(100, normal))

class Alarm:
    def __init__(self):
        self.listeners = []

    def on(self, fn):
        self.listeners.append(fn)

    def check(self, temp):
        if temp > 30:
            for fn in self.listeners:
                fn(temp)

a = Alarm()
a.on(lambda t: print(f'高温{t}°C!'))
a.check(35)
